package nir.com.neonvegasslots;
import static org.junit.Assert.*;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) public class WinCounterTest{
 void set(SlotsView v,String n,long x)throws Exception{Field f=SlotsView.class.getDeclaredField(n);f.setAccessible(true);f.setLong(v,x);}
 @Test public void counterRisesAndSettlesWithoutChangingPaidBalance()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());set(v,"lastWin",1234);set(v,"winStartAt",1000);long b=v.getBalance();assertEquals(0,v.displayedLastWin(1000));assertTrue(v.displayedLastWin(1250)>0);assertTrue(v.displayedLastWin(1250)<v.displayedLastWin(1750));assertEquals(1234,v.displayedLastWin(2100));assertEquals(1234,v.displayedLastWin(9000));assertEquals(b,v.getBalance());}
 @org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE) @Test public void counterFrame()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());v.layout(0,0,640,1040);long n=System.currentTimeMillis();set(v,"lastWin",100);set(v,"winStartAt",n-400);set(v,"winFlashUntil",n+1200);android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(640,1040,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));try(java.io.FileOutputStream f=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-smallwin-counter.png")){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}}
}
